arguments.command:
KUBECONFIG=/tmp/kubeconfig kubectl get deploy -n social-network -o json > /tmp/deployments.json && python3 -c "
import json
with open('/tmp/deployments.json') as f:
    data = json.load(f)
for item in data['items']:
    name = item['metadata']['name']
    containers = item['spec']['template']['spec']['containers']
    for c in containers:
        cmd = c.get('command', [])
        args = c.get('args', [])
        if cmd or args:
            print(f'=== {name} ({c[\"name\"]}) ===')
            if cmd: print(f'  cmd: {cmd}')
            if args: print(f'  args: {args}')
" 2>&1 | head -60
